#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's quoting undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"; fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line). Idempotent. Creates ENV_FILE at mode 0600; writes through a symlink
# and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────
#
# Mini Manager: first deploy (specs/step-6-phone-and-deploy.md, ADRs 0002, 0005, 0006). Run it from the repo root,
# on main, after the step 6 PR is merged: ./scripts/deploy-wizard.sh
#
# Production secrets never go to a file here: the database URL and the seed password live only in this shell while
# it runs, the deploy hook goes to GitHub with gh, and everything else you paste into Render's dashboard yourself.

TOTAL_STAGES=8
# No .env defaults for production values: every ask starts empty.
ENV_FILE=/dev/null

banner "Mini Manager: first deploy (free plans only)"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Before you start"
say "This sets up Neon (database), Brevo (email), Cloudinary (photos) and Render (the app),"
say "then migrates and seeds the production database. Nothing here needs a paid plan."
step "Be on main, up to date, with the step 6 PR merged:  git switch main && git pull"
step "Have reviewed every migration in api/migrations (ADR 0002): they run against Neon in stage 3."
step "Be logged in to GitHub's CLI:  gh auth status"
if ! command -v gh >/dev/null 2>&1 || ! gh auth status >/dev/null 2>&1; then
  warn "gh is not ready; the deploy hook stage will tell you how to set the secret by hand."
fi
note "Free-plan details change. If a site asks for payment beyond a card check, stop and ask before going on."
pause "Ready?"

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Neon: the production database"
open_url "https://console.neon.tech/signup"
step "Sign up (free, no card) or log in."
step "Create a project: name mini-manager, Postgres version 18, region AWS US East 1 (N. Virginia)."
step "Open the project's Connect panel. Turn connection pooling OFF, so migrations get a direct connection."
step "Copy the connection string. It starts postgres:// and should end with sslmode=require."
ask_secret NEON_DATABASE_URL "Paste the Neon connection string:"
if [[ "$NEON_DATABASE_URL" != postgres* ]]; then
  warn "That does not start with postgres. Run the wizard again and paste the full string."
  exit 1
fi
note "Kept only in this shell, for the next stage. You will also paste it into Render yourself."

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Neon: migrate and create the first Admin"
say "This runs make migrate, then make seed, against Neon. Only the database URL changes."
# Secrets reach make through its environment, never its arguments (which other programs can list while it runs).
# -e lets them win over the same names in your local .env; -s stops make from echoing its commands.
on_neon() { DATABASE_URL="$NEON_DATABASE_URL" make -s -e "$@"; }
note "Pending migrations on Neon:"
on_neon migrate-status 2>&1 | grep -E "Pending|Applied|-- " | sed 's/^/    /' || true
if confirm "Apply every pending migration to Neon now?"; then
  on_neon migrate
else
  warn "Not migrated. The app refuses to start until you run this stage again."
  exit 1
fi
say "Now you, the first Admin. Use your everyday email and a new password (not the local one)."
ask SEED_ADMIN_EMAIL "Your email:"
ask SEED_ADMIN_NAME "Your name (2 to 40 characters):"
ask_secret SEED_ADMIN_PASSWORD "A new password (8 to 72 characters):"
if confirm "Create this Admin on Neon now?"; then
  SEED_ADMIN_EMAIL="$SEED_ADMIN_EMAIL" SEED_ADMIN_PASSWORD="$SEED_ADMIN_PASSWORD" SEED_ADMIN_NAME="$SEED_ADMIN_NAME" on_neon seed
else
  unset SEED_ADMIN_PASSWORD
  warn "No Admin was created. Without one nobody can log in or invite anyone; run the wizard again."
  exit 1
fi
unset SEED_ADMIN_PASSWORD

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Brevo: email for invites and password resets (ADR 0006)"
open_url "https://onboarding.brevo.com/account/register"
step "Sign up for the free plan (no card) or log in."
step "Add a sender: your Gmail address, name Mini Manager. Click the link Brevo emails you to verify it."
step "Create an API key (in the SMTP & API section, API keys tab). Copy it; Brevo shows it once."
note "Leave this Brevo tab open: you copy the key from it straight into Render in stage 6."
note "Check the free plan still sends at least 300 emails a day without a card or a domain."
pause "Sender verified and API key copied?"

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Cloudinary: photos (ADR 0005)"
open_url "https://console.cloudinary.com/settings/security"
step "In Settings → Security, turn ON Strict transformations, then save."
note "Your uploads keep the phone's location data; this makes sure only the resized copies are ever shown."
step "Leave the Settings → API Keys page open: you copy the three values from it into Render in stage 6."
pause "Strict transformations is on?"

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Render: the app"
open_url "https://dashboard.render.com/web/new"
step "Sign up or log in with GitHub. If Render asks for a card, it is a check only; stay on Free."
step "New Web Service → connect the BarbieriM/MiniManager repository."
step "Name: mini-manager · Region: Virginia (US East) · Branch: main · Runtime: Docker · Instance: Free."
step "Under Advanced, set Auto-Deploy to Off (CI deploys main after its checks pass)."
note "Render shows the address under the name, such as https://mini-manager.onrender.com."
ask APP_BASE_URL "The service's address (https://….onrender.com):"
say ""
say "Add these environment variables (Add Environment Variable), copying each one straight from its own tab:"
step "DATABASE_URL           from the Neon tab (stage 2), pooling off"
step "APP_BASE_URL           $APP_BASE_URL"
step "EMAIL_FROM             Mini Manager <your.gmail@gmail.com>, the sender verified in Brevo"
step "BREVO_API_KEY          from the Brevo tab (stage 4)"
step "CLOUDINARY_CLOUD_NAME, CLOUDINARY_API_KEY, CLOUDINARY_API_SECRET   from the Cloudinary tab (stage 5)"
step "CLOUDINARY_FOLDER      prod"
step "JWT_SECRET             leave this one for last; the wizard makes it next"
pause "All of those added except JWT_SECRET?"
if command -v pbcopy >/dev/null 2>&1 && command -v openssl >/dev/null 2>&1; then
  openssl rand -base64 48 | tr -d '\n' | pbcopy
  say "A new JWT_SECRET is on your clipboard now (never shown). Paste it as the JWT_SECRET value in Render."
  pause "Pasted?"
  # Clear it, so the secret does not stay on the clipboard.
  printf '' | pbcopy
  note "Clipboard cleared."
else
  warn "No clipboard here. Run  openssl rand -base64 48  in another terminal and paste the result as JWT_SECRET."
  pause "Pasted?"
fi
step "Create the service. The first deploy takes a few minutes; it should end with 'server: listening'."
pause "Is the service live?"

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Render → GitHub: deploy on every merge to main"
step "In the Render service: Settings → Deploy Hook. Copy the URL (it is secret: anyone with it can deploy)."
ask_secret RENDER_DEPLOY_HOOK_URL "Paste the deploy hook URL:"
set_secret RENDER_DEPLOY_HOOK_URL "$RENDER_DEPLOY_HOOK_URL"
unset RENDER_DEPLOY_HOOK_URL NEON_DATABASE_URL
note "From now on, CI deploys main after lint, tests, end-to-end tests and the image build pass."

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Check it, then the phone test"
open_url "$APP_BASE_URL"
step "Log in with the Admin from stage 3. The first visit may show 'Waking the server' for up to a minute."
step "Members → Invite yourself at a second email. Check the email arrives (and its spam folder)."
step "On your phone: accept that invite, add a mini with a photo, find it with two filters."
step "As the Admin, open that mini and edit it; as another Member, check you cannot."
step "Take a sideways phone photo and check it shows upright."
pause "Done?"

finish
